-- =====================================================================
-- import_real_data.sql  V2真实场景AI生成版
-- 又见炊烟餐饮管理系统V2.0  维护:地龙(DL-BOT)  生成:2026-08-03
-- 业务链路(严格按序):
--   采购申请(2026-02-01)→审批(2026-02-05)→验收入库(2026-02-06)
--   →原料档案→出成率→成本换算→成本率→菜肴入库
-- AI生成原则:采购量/供应商/出成率/规格按真实餐厅采购场景算法生成
-- 单价用Excel真实值(ingredient_cost_data.csv), 不臆造
-- =====================================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

-- =====================================================================
-- 第一部分: 表与字段中文注释
-- =====================================================================
ALTER TABLE `purchase_order` COMMENT='采购订单表(申请→审批→下达, 记录采购主信息)';
ALTER TABLE `purchase_order_detail` COMMENT='采购订单明细表(每张订单的原料明细行)';
ALTER TABLE `purchase_receipt` COMMENT='采购收货表(验收+入库, 记录到货验收主信息)';
ALTER TABLE `purchase_receipt_detail` COMMENT='采购收货明细表(每批到货的原料验收明细行)';
ALTER TABLE `ingredient_master` COMMENT='原料主表(经采购入库后建立的原料档案, 含规格/单位/单价/出成率)';
ALTER TABLE `ingredient_cost_price` COMMENT='原料成本换算表(采购价÷出成率=净料成本单价)';
ALTER TABLE `yield_rate_config` COMMENT='原料出成率配置表(毛重→净重转换率, 行业标准值)';
ALTER TABLE `dish_master` COMMENT='菜肴主表(成本率校验通过后入库的菜肴档案, 含售价/成本/成本率)';

