-- =====================================================================
-- 第五部分: 验证导入结果
-- =====================================================================
SET FOREIGN_KEY_CHECKS=1;
SELECT '=== 采购订单(4批次,真实供应商) ===' AS info;
SELECT order_no,supplier_name,order_date,approve_time,status,(SELECT COUNT(*) FROM purchase_order_detail d WHERE d.order_id=o.order_id) AS 明细数,ROUND(total_amount,2) AS 总金额 FROM purchase_order o WHERE store_id=1;
SELECT '=== 采购明细抽样(真实采购单位/数量) ===' AS info;
SELECT ingredient_name,category,spec,unit,quantity,unit_price,amount,remark FROM purchase_order_detail WHERE store_id=1 ORDER BY RAND() LIMIT 15;
SELECT '=== 原料主档(真实规格/出成率) ===' AS info;
SELECT COUNT(*) AS 原料总数,COUNT(DISTINCT ingredient_category) AS 类别数,ROUND(AVG(yield_rate),2) AS 平均出成率 FROM ingredient_master WHERE store_id=1;
SELECT ingredient_category,COUNT(*) AS 数量,ROUND(AVG(yield_rate),2) AS 平均出成率 FROM ingredient_master WHERE store_id=1 GROUP BY ingredient_category ORDER BY 数量 DESC;
SELECT '=== 原料抽样(出成率真实性) ===' AS info;
SELECT ingredient_name,spec,purchase_unit,conversion_rate,unit_price,yield_rate FROM ingredient_master WHERE store_id=1 ORDER BY RAND() LIMIT 15;
SELECT '=== 成本换算(净料单价) ===' AS info;
SELECT COUNT(*) AS 记录数,ROUND(AVG(net_price_per_unit),6) AS 平均净料单价 FROM ingredient_cost_price WHERE store_id=1;
SELECT '=== 菜肴主表(348道真实菜) ===' AS info;
SELECT COUNT(*) AS 菜肴总数,COUNT(DISTINCT dish_category) AS 分类数,SUM(CASE WHEN cost_rate>0 THEN 1 ELSE 0 END) AS 有成本率数 FROM dish_master;
SELECT dish_category,COUNT(*) AS 数量 FROM dish_master GROUP BY dish_category ORDER BY 数量 DESC;
SELECT '=== 孤儿原料验证(应为0) ===' AS info;
SELECT COUNT(*) AS 无档案原料数 FROM dish_recipe dr LEFT JOIN ingredient_master im ON dr.ingredient_id=im.ingredient_id AND im.store_id=1 WHERE im.ingredient_id IS NULL;
